        ["settings.hash.detail"] = ("Check programs, installers, scripts, documents and archives against known malware by their SHA-256 fingerprint. Only the fingerprint is sent, never the file.", "Programları, kurulum dosyalarını, betikleri, belgeleri ve arşivleri SHA-256 parmak izleriyle bilinen kötü amaçlı yazılımlara karşı kontrol eder. Dosyanın kendisi değil, yalnızca parmak izi gönderilir."),
        ["settings.mbKey.title"] = ("MalwareBazaar (abuse.ch) Auth-Key", "MalwareBazaar (abuse.ch) Auth-Key"),
