        ["settings.admin.detail"] = ("Tell me when a program gets administrator rights or installs a system service, with who signed it and whether it's known malware.", "Bir program yönetici yetkisi aldığında veya sistem hizmeti kurduğunda; kimin imzaladığını ve bilinen bir kötü amaçlı yazılım olup olmadığını bana bildir."),
        ["settings.startup.title"] = ("Start with Windows", "Windows ile başlat"),
        ["settings.startup.detail"] = ("Download protection and alerts only work while Agamemnon is running in the notification area.", "İndirme koruması ve uyarılar yalnızca Agamemnon bildirim alanında çalışırken etkindir."),
        ["settings.engines.title"] = ("Scan engines", "Tarama motorları"),
        ["settings.engines.detail"] = ("ClamAV signatures update automatically every two hours. Add your own YARA rules (.yar) to the rules folder.", "ClamAV imzaları iki saatte bir otomatik güncellenir. Kendi YARA kurallarınızı (.yar) kurallar klasörüne ekleyebilirsiniz."),
