        // Help
        ["help.title"] = ("Help", "Yardım"),
        ["help.intro"] = ("Short answers to the questions people ask most. You don't need to know anything about computers.", "En çok sorulan soruların kısa yanıtları. Bilgisayar bilgisi gerekmez."),
        ["help.action.scan"] = ("Scan my computer now", "Bilgisayarımı şimdi tara"),
        ["help.action.welcome"] = ("Open the welcome guide", "Karşılama rehberini aç"),
        ["help.action.report"] = ("Report a problem", "Sorun bildir"),
        ["help.q.safe"] = ("How do I know I'm protected?", "Korunduğumu nasıl anlarım?"),
        ["help.a.safe"] = ("Look at the shield on the Ana sayfa / Dashboard page and in the notification area next to the clock. Green means everything is fine. Orange means something needs a click: the dashboard lists it with a button that fixes it. Red means a threat was found.", "Ana sayfadaki ve saatin yanındaki bildirim alanındaki kalkana bakın. Yeşil her şeyin yolunda olduğunu gösterir. Turuncu, bir şeyin tek tıkla düzeltilmesi gerektiği anlamına gelir: Ana sayfada onu düzelten bir düğmeyle birlikte listelenir. Kırmızı, bir tehdit bulunduğunu gösterir."),
        ["help.q.threat"] = ("A threat was found. What should I do?", "Bir tehdit bulundu. Ne yapmalıyım?"),
        ["help.a.threat"] = ("Press “Quarantine all threats” on the Scan page (or “Quarantine them” on the dashboard). That's all. The files are locked away and can't harm your computer anymore. Don't open the file first.", "Tarama sayfasında “Tüm tehditleri karantinaya al” düğmesine (veya ana sayfadaki “Karantinaya al” düğmesine) basın. Hepsi bu. Dosyalar kilitlenir ve artık bilgisayarınıza zarar veremez. Dosyayı önce açmayın."),
        ["help.q.quarantine"] = ("What is quarantine?", "Karantina nedir?"),
        ["help.a.quarantine"] = ("A locked box for dangerous files. Agamemnon encrypts them so they can't run or be opened. You can delete them for good, or restore one if you're sure it was a mistake.", "Tehlikeli dosyalar için kilitli bir kutu. Agamemnon bu dosyaları şifreler; böylece çalıştırılamaz ve açılamazlar. Onları tamamen silebilir ya da bir hata olduğundan eminseniz geri yükleyebilirsiniz."),
        ["help.q.restore"] = ("A file I need was put in quarantine.", "İhtiyacım olan bir dosya karantinaya alındı."),
        ["help.a.restore"] = ("Open Quarantine and press “Restore” next to the file. Only do this if you know exactly where the file came from and trust it. Agamemnon will remember your choice and won't block that file again.", "Karantina sayfasını açın ve dosyanın yanındaki “Geri yükle” düğmesine basın. Bunu yalnızca dosyanın nereden geldiğini kesin olarak biliyor ve ona güveniyorsanız yapın. Agamemnon seçiminizi hatırlar ve o dosyayı bir daha engellemez."),
        ["help.q.scan"] = ("How often should I scan?", "Ne sıklıkla tarama yapmalıyım?"),
        ["help.a.scan"] = ("You don't have to remember: Agamemnon runs a quick scan every week by itself (you can change this in Settings) and checks every download as it arrives. Run a full scan if you think something is wrong.", "Hatırlamanıza gerek yok: Agamemnon her hafta kendi kendine hızlı tarama yapar (bunu Ayarlar'dan değiştirebilirsiniz) ve her indirmeyi geldiği anda kontrol eder. Bir sorun olduğunu düşünüyorsanız tam tarama yapın."),
        ["help.q.dns"] = ("What does “private browsing (encrypted DNS)” do?", "“Gizli gezinme (şifreli DNS)” ne işe yarar?"),
        ["help.a.dns"] = ("Every time you open a website, your computer asks “where is this site?”. Normally anyone on your network can read that question. Encrypted DNS hides it, and the recommended server also refuses to open known scam and malware sites. If websites stop opening on a hotel or café Wi-Fi, turn it off there.", "Bir web sitesini her açtığınızda bilgisayarınız “bu site nerede?” diye sorar. Normalde ağınızdaki herkes bu soruyu okuyabilir. Şifreli DNS bunu gizler; önerilen sunucu ayrıca bilinen dolandırıcılık ve zararlı siteleri açmayı reddeder. Otel veya kafe Wi-Fi'sinde siteler açılmazsa orada kapatın."),
        ["help.q.admin"] = ("What is an administrator-rights warning?", "Yönetici yetkisi uyarısı nedir?"),
        ["help.a.admin"] = ("Administrator rights let a program change anything on your computer. When you install software, this is normal. If you get this warning and you didn't just install or update something, run a full scan.", "Yönetici yetkisi bir programın bilgisayarınızdaki her şeyi değiştirmesine izin verir. Bir program kurarken bu normaldir. Bu uyarıyı aldığınızda az önce bir şey kurmadıysanız veya güncellemediyseniz tam tarama yapın."),
        ["help.q.engine"] = ("It says a service or the scan engine isn't running.", "Bir hizmetin veya tarama motorunun çalışmadığı yazıyor."),
        ["help.a.engine"] = ("Restart your computer; this fixes it almost every time. If the message comes back, download the latest Agamemnon setup and run it again: it repairs the installation and keeps your settings.", "Bilgisayarınızı yeniden başlatın; bu neredeyse her zaman sorunu çözer. Mesaj geri gelirse en son Agamemnon kurulum dosyasını indirip yeniden çalıştırın: kurulumu onarır ve ayarlarınızı korur."),
        ["help.q.defender"] = ("Should I turn off Microsoft Defender?", "Microsoft Defender'ı kapatmalı mıyım?"),
        ["help.a.defender"] = ("No. Keep Defender on. Agamemnon works alongside it and adds download blocking, encrypted DNS, extra malware databases and administrator-rights warnings.", "Hayır. Defender'ı açık tutun. Agamemnon onunla birlikte çalışır ve indirme engelleme, şifreli DNS, ek kötü amaçlı yazılım veritabanları ve yönetici yetkisi uyarıları ekler."),
        ["help.q.privacy"] = ("Does Agamemnon send my files anywhere?", "Agamemnon dosyalarımı bir yere gönderiyor mu?"),
        ["help.a.privacy"] = ("No. Files are checked on your computer. With hash lookups on, only a short fingerprint of a file is sent to MalwareBazaar or VirusTotal, never the file itself.", "Hayır. Dosyalar bilgisayarınızda kontrol edilir. Özet sorgulama açıksa MalwareBazaar'a veya VirusTotal'a dosyanın kendisi değil, yalnızca kısa bir parmak izi gönderilir."),
        ["help.q.language"] = ("How do I change the language?", "Dili nasıl değiştiririm?"),
        ["help.a.language"] = ("Click “English” or “Türkçe” at the bottom of the left sidebar, or go to Settings. The whole app switches right away.", "Sol menünün altındaki “English” veya “Türkçe” düğmesine tıklayın ya da Ayarlar'a gidin. Uygulamanın tamamı hemen değişir."),

        // About
        ["about.version"] = ("Version {0} for Windows", "Windows için sürüm {0}"),
        ["about.description"] = ("Open-source antivirus for Windows and Mac: encrypted DNS, malware scanning against more than 50 million known threats, archive and installer scanning, unsafe-download blocking and administrator-rights alerts.", "Windows ve Mac için açık kaynaklı antivirüs: şifreli DNS, 50 milyondan fazla bilinen tehdide karşı kötü amaçlı yazılım taraması, arşiv ve kurulum dosyası taraması, tehlikeli indirme engelleme ve yönetici yetkisi uyarıları."),
