        ["welcome.back"] = ("Back", "Geri"),
        ["welcome.finish"] = ("Finish", "Bitir"),
        ["welcome.what.title"] = ("What Agamemnon does for you", "Agamemnon sizin için ne yapar"),
        ["welcome.what.1"] = ("✓  Checks every file you download and locks dangerous ones away.", "✓  İndirdiğiniz her dosyayı kontrol eder ve tehlikeli olanları kilitler."),
        ["welcome.what.2"] = ("✓  Scans your computer for more than 50 million known threats.", "✓  Bilgisayarınızı 50 milyondan fazla bilinen tehdide karşı tarar."),
        ["welcome.what.3"] = ("✓  Hides the websites you visit from your network (encrypted DNS).", "✓  Ziyaret ettiğiniz siteleri ağınızdan gizler (şifreli DNS)."),
        ["welcome.what.4"] = ("✓  Warns you when a program takes full control of your PC.", "✓  Bir program bilgisayarınızın tam kontrolünü aldığında sizi uyarır."),
        ["welcome.new.title"] = ("New in 3.0", "3.0'daki yenilikler"),
        ["welcome.new.1"] = ("•  Turkish and English: switch at any time from the sidebar.", "•  Türkçe ve İngilizce: sol menüden istediğiniz an değiştirin."),
        ["welcome.new.2"] = ("•  One-click fixes: the dashboard shows what's wrong and a button that fixes it.", "•  Tek tıkla düzeltme: ana sayfa neyin yanlış olduğunu ve onu düzelten düğmeyi gösterir."),
        ["welcome.new.3"] = ("•  Automatic weekly scans, protection switches on the dashboard, and simple mode.", "•  Haftalık otomatik tarama, ana sayfada koruma anahtarları ve basit mod."),
        ["welcome.new.4"] = ("•  A Help page with plain answers to common questions.", "•  Sık sorulan sorulara sade yanıtlar veren Yardım sayfası."),
        ["welcome.new.kept"] = ("Your settings, quarantine and threat database from version 2.0 were kept.", "2.0 sürümündeki ayarlarınız, karantinanız ve tehdit veritabanınız korundu."),
        ["welcome.setup.title"] = ("Set up your protection", "Korumanızı ayarlayın"),
        ["welcome.setup.detail"] = ("The recommended setup suits almost everyone. You can change any of it later in Settings.", "Önerilen ayarlar neredeyse herkese uygundur. Hepsini daha sonra Ayarlar'dan değiştirebilirsiniz."),
        ["welcome.setup.recommended"] = ("Use the recommended setup", "Önerilen ayarları kullan"),
        ["welcome.setup.dns.detail"] = ("Uses Cloudflare's security server, which also blocks known scam and malware sites.", "Bilinen dolandırıcılık ve zararlı siteleri de engelleyen Cloudflare güvenlik sunucusunu kullanır."),
        ["welcome.setup.autoScan"] = ("Scan automatically every week", "Her hafta otomatik tara"),
        ["welcome.setup.autoScan.detail"] = ("A quick scan in the background. You only hear about it if something is found.", "Arka planda hızlı bir tarama. Yalnızca bir şey bulunursa haberiniz olur."),
        ["welcome.done.title"] = ("You're all set", "Her şey hazır"),
